```javascript
function renderProducts(productsToShow) {
    const grid = document.getElementById("product-grid");
    const countDisplay = document.getElementById("count-display");

    if (productsToShow.length === 0) {
        grid.innerHTML = `<div class="col-12 text-center py-5">
            <h4 class="text-muted">No products found</h4>
            <p>Try a different search or category</p>
        </div>`;
        countDisplay.textContent = "No products found";
        return;
    }

    countDisplay.textContent = `Showing ${productsToShow.length} product${productsToShow.length > 1 ? 's' : ''}`;

    grid.innerHTML = productsToShow.map(p => `
        <div class="col-md-6 col-lg-4 col-xl-3">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <div style="font-size: 3rem;">${p.image}</div>
                    <span class="badge bg-secondary mb-2">${p.category}</span>
                    <h5 class="card-title">${p.name}</h5>
                    <p class="card-text text-muted small">${p.desc}</p>
                    <p class="fw-bold fs-5">₹${p.price.toLocaleString("en-IN")}</p>
                    <button class="btn btn-primary btn-sm" onclick="addToCart('${p.name}')">
                        Add to Cart
                    </button>
                </div>
            </div>
        </div>
    `).join("");
}

// Initial render
renderProducts(products);
```

Save and check — you should see all 10 product cards in a responsive grid.

```javascript
const searchInput = document.getElementById("search");
const categoryFilter = document.getElementById("category-filter");

function applyFilters() {
    const searchTerm = searchInput.value.toLowerCase().trim();
    const category = categoryFilter.value;

    let filtered = products;

    // Filter by category
    if (category !== "all") {
        filtered = filtered.filter(p => p.category === category);
    }

    // Filter by search
    if (searchTerm) {
        filtered = filtered.filter(p =>
            p.name.toLowerCase().includes(searchTerm) ||
            p.desc.toLowerCase().includes(searchTerm)
        );
    }

    renderProducts(filtered);
}

// Real-time search (fires on every keystroke)
searchInput.addEventListener("input", applyFilters);

// Category dropdown
categoryFilter.addEventListener("change", applyFilters);

